// Extract contact data from AI agent output
const input = $input.item.json;

// Function to safely extract field
function extractField(data, possibleKeys) {
  for (const key of possibleKeys) {
    if (data[key] && typeof data[key] === 'string' && data[key].trim()) {
      return data[key].trim();
    }
  }
  return '';
}

// Extract Full Name
const fullName = extractField(input, ['Full_Name', 'Full Name', 'fullName', 'name', 'Full_Name_']);

// Extract Email
const email = extractField(input, ['Email_Address', 'Email Address', 'email', 'Email_Address_']);

// Validation
if (!fullName || !email) {
  throw new Error(`Missing required fields: ${!fullName ? 'Full Name' : ''} ${!email ? 'Email' : ''}`);
}

// Validate email format
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
if (!emailRegex.test(email)) {
  throw new Error('Invalid email format: ' + email);
}

// Return structured data for Airtable
return {
  json: {
    'Full Name': fullName,
    'Email Address': email.toLowerCase(),
    'Phone Number': extractField(input, ['Phone_Number', 'Phone Number', 'phone', 'Phone_Number_']),
    'Company Name': extractField(input, ['Company_Name', 'Company Name', 'company', 'Company_Name_']),
    'Address': extractField(input, ['Address', 'address']),
    'Client Summary (AI)': extractField(input, ['Client_Summary__AI_', 'Client Summary (AI)', 'summary', 'clientSummary']),
    'Client Type (AI)': extractField(input, ['Client_Type', 'Client Type (AI)', 'clientType', 'type'])
  }
};
